function transform(root, ctx = { inVFor: false }) {
  const hoisted = []
  function walk(node, parent, idx) {
    if (node.type === 0 || node.type === 1) {
      // post-order：先处理孩子（自底向上才能整体判定静态）
      for (let i = 0; i < (node.children || []).length; i++)
        walk(node.children[i], node, i)
    }
    if (node.type !== 1) return
    let flag = 0, dynNames = []
    for (const p of node.props || []) {
      if (p.value === null) { flag |= 4; dynNames.push(p.name) } // 动态绑定
      else if (p.name === 'key') return // key 节点不可 hoist（Vue 真实规则示意）
    }
    if ((node.children || []).some((c) => c.type === 3)) flag |= 1
    node.patchFlag = flag || undefined
    node.dynamicProps = dynNames.length ? dynNames : undefined
    if (!flag && !ctx.inVFor && parent && parent.type === 1) {
      hoisted.push(node)
      parent.children[idx] = node // 真实 Vue：hoist 后原位留 HOISTED 引用(-1)
      node.patchFlag = -1
    }
  }
  walk(root)
  return { ast: root, hoisted }
}
